                titleBn = "ক্ষমা চাওয়ার সর্বশ্রেষ্ঠ দোয়া: সাইয়্যিদুল ইস্তিগফার",
                arabicText = "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ",
                pronunciationBn = "আল্লাহুম্মা আনতা রব্বী লা-ইলাহা ইল্লা আনতা খালাক্কতানী ওয়া আনা আ’বদুকা ওয়া আনা আ’লা আহদিকা ওয়া ও’য়াদিকা মাসতাত’তু আ’উযুবিকা মিন শার্রি মা ছা’নাতু আবূউলাকা বিনি’মাতিকা আ’লাইয়্যা ওয়া আবূউলাকা বিযানবী ফাগফির্লি ফাইন্নাহু লা-ইয়াগফিরুয্যুনূবা ইল্লা আনতা।",
                meaningBn = "হে আল্লাহ তুমিই আমার প্রতিপালক। তুমি ছাড়া কোন ইলাহ নেই। তুমিই আমাকে সৃষ্টি করেছ। আমি তোমারই গোলাম। আমি যথাসাধ্য তোমার সঙ্গে প্রতিজ্ঞা ও অঙ্গীকারের উপর আছি। আমি আমার সব কৃতকর্মের কুফল থেকে তোমার কাছে পানাহ চাচ্ছি। তুমি আমার প্রতি তোমার যে নিয়ামত দিয়েছ তা স্বীকার করছি। আর আমার কৃত গুনাহের কথাও স্বীকার করছি। তুমি আমাকে মাফ করে দাও। কারণ তুমি ছাড়া কেউ গুনাহ ক্ষমা করতে পারবে না।",
