                repetitionOrTimeBn = "সহীহ হাদিসের আলোকবর্তিকা",
                titleBn = "ক্ষমা প্রার্থনা ও তাওবা সম্পর্কে নবীজী (ﷺ)-এর সুবর্ণ বাণী",
                arabicText = "إِنَّهُ لَيُغَانُ عَلَى قَلْبِي وَإِنِّي لَأَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ مِائَةَ مَرَّةٍ",
                pronunciationBn = "ইন্নাহূ লাইউগ আনু আলা ক্বালবী ওয়া ইন্নী লা-আসতাগফিরুল্লা-হা ফিল ইয়াওমি মি'আতা মাররাহ।",
                meaningBn = "১. রাসুলুল্লাহ ﷺ বলেন: “আল্লাহর শপথ, নিশ্চয় আমি দৈনিক সত্তর-এর অধিকবার আল্লাহর কাছে ক্ষমা চাই এবং তাওবা করি।” [সহীহ বুখারী: ৬৩০৭]\n\n২. রাসুলুল্লাহ ﷺ আরও বলেন: “হে মানুষ, তোমরা আল্লাহর কাছে তাওবা কর, নিশ্চয় আমি আল্লাহর কাছে দৈনিক একশত বার তাওবা করি।” [সহীহ মুসলিম: ২৭০২]\n\n৩. রবের সর্বাধিক সান্নিধ্য লাভ: “রব একজন বান্দার সবচেয়ে বেশি নিকটবর্তী হন রাতের শেষ প্রান্তে (তাহাজ্জুদের শেষ প্রহরে)। সুতরাং যদি তুমি সে সময়ে আল্লাহর যিক্রকারীদের অন্তর্ভুক্ত হতে সক্ষম হও, তবে তা-ই হও।” [তিরমিযী: ৩৫৭৯, নাসায়ী: ৫৭২]\n\n৪. সিজদায় রবের নৈকট্য: “একজন বান্দা তার রবের সবচেয়ে কাছে তখনই থাকে, যখন সে সিজদায় যায়। সুতরাং তোমরা তখন বেশি বেশি করে দো'আ কর।” [সহীহ মুসলিম: ৪৮২]\n\n৫. অন্তরের পবিত্রতা ও ইস্তিগফার: “নিশ্চয় আমার অন্তরেও আবরণ এসে পড়ে, আর আমি দৈনিক আল্লাহর কাছে একশত বার ক্ষমা প্রার্থনা করি।” [সহীহ মুসলিম: ২৭০২] — সামান্যতম অন্যমনস্কতা দেখা দিলেই নবীজী ﷺ দ্রুত ক্ষমা প্রার্থনায় মশগুল হতেন।",
                fojilotBn = "নবী করীম ﷺ নিষ্পাপ হওয়া সত্ত্বেও দৈনিক ১০০ বার ইস্তিগফার করতেন, রাতের শেষ প্রহরে ও সিজদায় রবের নিকটবর্তী হয়ে কান্নাকাটি করতেন।",
                referenceBn = "সহীহ বুখারী: ৬৩০৭, সহীহ মুসলিম: ২৭০২, ৪৮২, তিরমিযী: ৩৫৭৯"
            ),

            // ১৪. তওবা ও ইস্তেগফার সম্পর্কিত গুরুত্বপূর্ণ সচরাচর প্রশ্নোত্তর (FAQ Section)
            IslamicLifeCardItem(
