                serialNumberBn = "১৪",
                repetitionOrTimeBn = "সংশয় নিরসন ও প্রশ্নোত্তর (FAQ)",
                titleBn = "১৪. তওবা ও ইস্তেগফার সম্পর্কিত সচরাচর প্রশ্নোত্তর (FAQ Section)",
                arabicText = "وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ",
                pronunciationBn = "ওয়া তূবূ ইলাল্লাহি জামী'আন আইয়্যুহাল মু'মিনূনা লা'আল্লাকুম তুফলিহূন।",
                meaningBn = "তওবা ও ইস্তেগফার বিষয়ক সবচেয়ে গুরুত্বপূর্ণ সচরাচর ৫টি প্রশ্নের প্রামাণ্য উত্তর:\n\n❓ প্রশ্ন ১: তওবা করতে কি কোনো মৌলভী, হুজুর বা পীর সাহেবের মধ্যস্থতা প্রয়োজন?\nউত্তর: একেবারেই না। ইসলামে আল্লাহ ও বান্দার মাঝে কোনো পুরোহিত বা মধ্যস্থতাকারী নেই। বান্দা যেকোনো স্থান থেকে একাকী বিনম্র চিত্তে দু'হাত তুলে নিজের অপরাধ স্বীকার করে সরাসরি মহান আল্লাহর কাছে ক্ষমা চাইবে। আল্লাহ তাআলা সরাসরি তওবা কবুল করেন।\n\n❓ প্রশ্ন ২: বারবার একই পাপে লিপ্ত হয়ে গেলে কি পুনরায় তওবা কবুল হবে?\nউত্তর: হ্যাঁ। বান্দা যতবারই দুর্বলতাবশত পাপে জড়িয়ে পড়বে, ততবারই আন্তরিকভাবে লজ্জিত হয়ে তওবা করলে আল্লাহ তাআলা প্রতিবারই ক্ষমা করবেন (সহীহ বুখারী: ৭৫৭২)। তবে শর্ত হলো, তওবার সময় ভবিষ্যতে আর না করার খাঁটি সংকল্প থাকতে হবে; পাপের পরিকল্পনা রেখে তওবা করা প্রতারণা।\n\n❓ প্রশ্ন ৩: তওবার সালাত (সালাতুত তাওবা) আদায়ের নিয়ম ও বিধান কী?\nউত্তর: কোনো গুনাহ হয়ে গেলে উত্তমরূপে ওযু করে একাগ্রচিত্তে দুই রাকাত নফল সালাত আদায় করা এবং সালাত শেষে আল্লাহর কাছে ক্ষমা চাওয়া অত্যন্ত মর্যাদাপূর্ণ সুন্নাত আমল। রাসুলুল্লাহ ﷺ বলেছেন: “যে কোনো ব্যক্তি কোনো পাপে লিপ্ত হওয়ার পর ওজু করে দুই রাকাত সালাত আদায় করে ক্ষমা চাইলে আল্লাহ তাকে ক্ষমা করে দেন।” (সুনান আবু দাউদ: ১৫২১, জামে তিরমিযী: ৪০৬)।\n\n❓ প্রশ্ন ৪: তওবা কবুল হয়েছে কি না তা বোঝার আলামত বা লক্ষণগুলো কী কী?\nউত্তর: প্রধান ৪টি আলামত— ১. পূর্বের পাপের প্রতি অন্তরে চরম ঘৃণা সৃষ্টি হওয়া। ২. সৎকাজে আনন্দ ও অনুপ্রেরণা বৃদ্ধি পাওয়া। ৩. পূর্বের অসৎ সঙ্গীদের সঙ্গ চিরতরে বর্জন করা। ৪. অন্তরে এক অনাবিল প্রশান্তি, বিনম্রতা ও আল্লাহভীতি জাগ্রত থাকা।\n\n❓ প্রশ্ন ৫: কোন সময় তওবা করার সুযোগ চিরতরে বন্ধ হয়ে যায়?\nউত্তর: দুটি মুহূর্তে তওবার দরজা সম্পূর্ণ বন্ধ হয়ে যায়— ১. মৃত্যুর লক্ষণ প্রকাশ পেলে ও কণ্ঠনালীতে প্রাণবায়ু আটকে গেলে (গরগরা শুরু হলে - জামে তিরমিযী: ৩৫৩৭)। ২. কিয়ামতের প্রাক্কালে পশ্চিম দিগন্তে সূর্য উদিত হলে (সহীহ মুসলিম: ২৭০১)।",
