                pronunciationBn = "ওয়াস-সাবিরীনা ফিল বা’সা-য়ি ওয়াদ-দাররা-য়ি ওয়াহী-নাল বা’স।",
                meaningBn = "💠 আল্লাহর নিকট ক্ষমা চাইলে রহমতের দুয়ার খুলে যায়:\nইমাম ইবনে তাইমিয়াহ (রহ.) বলেছেন— “যখন আমি কোনো ধর্মীয় বিষয় বুঝতে পারছিলাম না, তখন আমি এক হাজার বার আল্লাহর নিকট ক্ষমা প্রার্থনা (ইস্তিগফার) করতাম; এরপরই আল্লাহ আমাকে তা বোঝার তাওফীক দান করতেন।”\n\nকুরআনে রয়েছে: “তোমরা তোমাদের প্রভুর নিকট ক্ষমা প্রার্থনা কর, নিশ্চয় তিনি মহা ক্ষমাশীল। তিনি তোমাদের উপর প্রচুর বৃষ্টি বর্ষণ করবেন।” (সূরা নূহ: ১০-১১)\n\n💠 সংকটে পাহাড়সম ঈমানী অটলতা:\n• সাওর গুহায় রাসুলুল্লাহ ﷺ ও আবু বকর (রা.): শত্রু যখন গুহার মুখে, তখন নবীজী ﷺ অবিচল কণ্ঠে বলেছিলেন: “হতাশ হবেন না, নিশ্চয়ই আল্লাহ আমাদের সাথে আছেন।” (সূরা তাওবা: ৪০)।\n• বদরের ময়দানে বর্ম পরিধানকালে রাসুলুল্লাহ ﷺ-এর অটল বিশ্বাস: “এই দল তো অচিরেই পরাজিত হবে এবং পিঠ দেখিয়ে পালাবে।” (সূরা ক্বামার: ৪৫)।\n• ওহুদের ময়দানে নবীজী ﷺ-এর অবিচলতা: বহু সাহাবী শহীদ হওয়ার পরও তিনি সাহাবীদের নিয়ে রবের হামদ ও সান্নিধ্যে দাঁড়ালেন।\n• ইয়ারমুকের ময়দানে সাহাবীগণের চরম আত্মত্যাগ: নিজে পিপাসার্ত থাকা সত্ত্বেও পানি অন্য মুসলিম ভাইয়ের দিকে ঠেলে দিয়ে শাহাদাত বরণ করলেন।",
